	public static boolean isEmpty(String str){
		return str == null || "".equals(str);
	}


	public static boolean isNotEmpty(String str){
		return !isEmpty(str);
	}

	public static String hexToString(String s) {
		StringBuilder sb = new StringBuilder();
		if (s != null && s.length() % 4 == 0) {
			int i = 0;
			while (s.length() > i) {
				String substring = s.substring(i, i + 4);
				// System.out.println(substring);
				// // Integer.toHexString(i)
				int valueOf = Integer.valueOf(substring, 16);
				// System.out.println((char)valueOf);
				sb.append((char) valueOf);
				i += 4;
			}
		}

		return sb.toString();
	}


	public static byte[] inputStreamToByteArray(InputStream is){
		byte[] result = null;

		try {
			int len = -1;
			byte[] buffer = new byte[1024];
			ByteArrayOutputStream baos = new ByteArrayOutputStream();
			while ( (len = is.read(buffer)) != -1) {
				baos.write(buffer, 0, len);
			}
			result = baos.toByteArray();
			baos.flush();
			baos.close();
			is.close();
		} catch (Exception e) {
			e.printStackTrace();
		}

		return result;
	}

	public static String unioncodName(String unioName) {
		String result = "";
		for (int j = 0; j < unioName.length(); j = j + 4) {
			String str = unioName.substring(0 + j, 4 + j);
			String tmp = convertUnicodeToChar("\\u" + str);
			result = result + tmp;
		}
		//System.err.println("wwwwwwww, result:" + result);
		return result;
	}

	/**
	 * 
	 * @param source
	 * @return
	 */
	public static String convertUnicodeToChar(String source) {
		if (null == source || " ".equals(source)) {
			return source;
		}

		StringBuffer sb = new StringBuffer();
		int i = 0;
		while (i < source.length()) {
			if (source.charAt(i) == '\\') {
				int j = Integer.parseInt(source.substring(i + 2, i + 6), 16);
				sb.append((char) j);
				i += 6;
			} else {
				sb.append(source.charAt(i));
				i++;
			}
		}
		return sb.toString();
	}

    public static String decodeHexToCh(String bytes){  
        byte[] baKeyword = new byte[bytes.length()/2];  
        for(int i = 0; i < baKeyword.length; i++){  
            try{  
                baKeyword[i] = (byte)(0xff & Integer.parseInt(bytes.substring(i*2, i*2+2),16));  
            }catch(Exception e){  
                e.toString();
            }  
        }  
        try{  
            bytes = new String(baKeyword, "GB2312");  
        }catch (Exception e1){  
            e1.toString();
        }  
        return bytes;  
      } 

	public static byte[] hexStringToBytes(String hexString) {  
	    if (hexString == null || hexString.equals("")) {  
	        return null;  
	    }  
	    hexString = hexString.toUpperCase();  
	    int length = hexString.length() / 2;  
	    char[] hexChars = hexString.toCharArray();  
	    byte[] d = new byte[length];  
	    for (int i = 0; i < length; i++) {  
	        int pos = i * 2;  
	        d[i] = (byte) (charToByte(hexChars[pos]) << 4 | charToByte(hexChars[pos + 1]));  
	    }  
	    return d;  
	}

	private static byte charToByte(char c) {  
	    return (byte) "0123456789ABCDEF".indexOf(c);  
	} 

	public static boolean isContainChinese(String str) {
	     Pattern p = Pattern.compile("[\u4e00-\u9fa5]");
	     Matcher m = p.matcher(str);
	     if (m.find()) {
	        return true;
	     }
	     return false;
	 }

	 public static boolean isContainSpecialChars(String str) {
	 	if (str.contains("[") || str.contains("]") || str.contains("*") || str.contains(",")) {
	 		return true;
	 	}
	 	return false;
	 }

	 public static String md5(String data) throws NoSuchAlgorithmException {  
	    MessageDigest md = MessageDigest.getInstance("MD5");  
	    md.update(data.getBytes());  
	    StringBuffer buf = new StringBuffer();  
	    byte[] bits = md.digest();  
	    for(int i=0;i<bits.length;i++){  
	         int a = bits[i];  
	         if(a<0) a+=256;  
	         if(a<16) buf.append("0");  
	         buf.append(Integer.toHexString(a));  
	    }  
	    return buf.toString();  
	 }  

