	/**
	 * 字符串转换unicode
	 * @return
	 */
	public static String string2Unicode(String input) {
		StringBuilder unicodeString = new StringBuilder();
		for (int i = 0; i < input.length(); i++) {
			char c = input.charAt(i);
//            unicodeString.append("\\u").append(String.format("%04X", (int) c));
			unicodeString.append(String.format("%04x", (int) c));
		}
		return unicodeString.toString();
	}

	public static String unicodeToString(String unicode) {
		StringBuilder result = new StringBuilder();

		// 每4个字符代表一个Unicode码
		for (int i = 0; i < unicode.length(); i += 4) {
			String hex = unicode.substring(i, i + 4); // 提取4个字符
			int charCode = Integer.parseInt(hex, 16); // 将16进制转为整数
			result.append((char) charCode); // 转换为字符并追加到结果
		}

		return result.toString();
	}
	public static String replaceBlank(String str) {
		String dest = "";
		if (str!=null) {
			Pattern p = Pattern.compile("\\s*|\t|\r|\n");
			Matcher m = p.matcher(str);
			dest = m.replaceAll("");
		}
		return dest;
	}

	public static int parseWeekStr(String freq) {
		String weekStr = freq.substring(0, 1) + freq.substring(6, 7) + freq.substring(5, 6)
				+ freq.substring(4, 5) + freq.substring(3, 4) + freq.substring(2, 3) 
				+ freq.substring(1, 2);
		int week = Integer.parseInt(weekStr, 2);
		return week;
	}

	  public static String hexStr2Str(String hexStr)  {    
        String str = "0123456789ABCDEF";    
        char[] hexs = hexStr.toCharArray();    
        byte[] bytes = new byte[hexStr.length() / 2];    
        int n;    

        for (int i = 0; i < bytes.length; i++)  {    
            n = str.indexOf(hexs[2 * i]) * 16;    
            n += str.indexOf(hexs[2 * i + 1]);    
            bytes[i] = (byte) (n & 0xff);    
        }    
        return new String(bytes);    
    }  
    public static String bytes2BinaryStr(byte[] bArray){  
        String outStr = "";  
        int pos = 0;  
        for(byte b:bArray){  
            pos = (b&0xF0)>>4;  
            outStr+=binaryArray[pos];   
            pos=b&0x0F;  
            outStr+=binaryArray[pos];  
        }  
        return outStr;  

    } 
	public static String str2HexStr(String str){      
	    char[] chars = "0123456789ABCDEF".toCharArray();      
	    StringBuilder sb = new StringBuilder();    
	    byte[] bs = str.getBytes();      
	    int bit;      

	    for (int i = 0; i < bs.length; i++) {      
	        bit = (bs[i] & 0x0f0) >> 4;      
	        sb.append(chars[bit]);      
	        bit = bs[i] & 0x0f;      
	        sb.append(chars[bit]);    
	        //sb.append(' ');    
	    }      
	    return sb.toString().trim();      
	}
