 * 增强版：解决乱码问题，提高健壮性
 */

public class FileRenamer extends JFrame {
    private JTextField directoryField;
    private JTextField prefixField;
    private JTextField digitsField;
    private JButton browseButton;
    private JButton renameButton;
    private JTextArea logArea;
    private JComboBox<String> sortOrderComboBox;
    private JComboBox<String> namingOrderComboBox;

    public FileRenamer() {
        initComponents();
        setupLayout();
        setupListeners();
    }

    private void initComponents() {
        setTitle("文件重命名工具");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(900, 500);
        setLocationRelativeTo(null);

        directoryField = new JTextField();
        prefixField = new JTextField("文件");
        digitsField = new JTextField("4");
        browseButton = new JButton("浏览");
        renameButton = new JButton("执行重命名");
        logArea = new JTextArea();
        logArea.setEditable(false);

        // 排序方式选择
        String[] sortOrders = {"按文件名升序", "按文件名降序", "按修改时间升序", "按修改时间降序"};
        sortOrderComboBox = new JComboBox<>(sortOrders);

        // 命名顺序选择
        String[] namingOrders = {"正序命名", "倒序命名"};
        namingOrderComboBox = new JComboBox<>(namingOrders);
    }

    private void setupLayout() {
        JPanel mainPanel = new JPanel(new BorderLayout(10, 10));
        mainPanel.setBorder(new EmptyBorder(10, 10, 10, 10));

        // 左侧控制面板
        JPanel controlPanel = new JPanel(new BorderLayout(10, 10));
        controlPanel.setPreferredSize(new Dimension(400, 0));

        // 目录选择面板
        JPanel directoryPanel = new JPanel(new BorderLayout(5, 5));
        directoryPanel.setBorder(BorderFactory.createTitledBorder("选择目录"));
        setupDragAndDrop(directoryField);
        directoryPanel.add(directoryField, BorderLayout.CENTER);
        directoryPanel.add(browseButton, BorderLayout.EAST);

        // 设置面板
        JPanel settingsPanel = new JPanel(new GridLayout(5, 2, 10, 10));
        settingsPanel.setBorder(BorderFactory.createTitledBorder("重命名设置"));

        // 前缀设置
        settingsPanel.add(new JLabel("文件前缀:"));
        settingsPanel.add(prefixField);

        // 数字位数设置
        settingsPanel.add(new JLabel("数字位数:"));
        settingsPanel.add(digitsField);

        // 排序方式
        settingsPanel.add(new JLabel("排序方式:"));
        settingsPanel.add(sortOrderComboBox);

        // 命名顺序
        settingsPanel.add(new JLabel("命名顺序:"));
        settingsPanel.add(namingOrderComboBox);

        // 空标签占位
        settingsPanel.add(new JLabel());
        settingsPanel.add(renameButton);

        // 右侧日志面板
        JPanel logPanel = new JPanel(new BorderLayout());
        logPanel.setBorder(BorderFactory.createTitledBorder("操作日志"));
        logPanel.setPreferredSize(new Dimension(400, 0));

        JScrollPane logScrollPane = new JScrollPane(logArea);
        logScrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_ALWAYS);
        logScrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        logPanel.add(logScrollPane, BorderLayout.CENTER);

        // 添加清除日志按钮
        JPanel logButtonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        JButton clearLogButton = new JButton("清除日志");
        clearLogButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                logArea.setText("");
            }
        });
        logButtonPanel.add(clearLogButton);
        logPanel.add(logButtonPanel, BorderLayout.SOUTH);

        // 组装控制面板
        controlPanel.add(directoryPanel, BorderLayout.NORTH);
        controlPanel.add(settingsPanel, BorderLayout.CENTER);

        // 组装主面板
        mainPanel.add(controlPanel, BorderLayout.WEST);
        mainPanel.add(logPanel, BorderLayout.CENTER);

        add(mainPanel);
    }

    private void setupDragAndDrop(JTextField textField) {
        new DropTarget(textField, new DropTarget() {
            @Override
            public synchronized void drop(DropTargetDropEvent dtde) {
                try {
                    dtde.acceptDrop(java.awt.dnd.DnDConstants.ACTION_COPY);
                    java.util.List<File> droppedFiles = (java.util.List<File>)
                            dtde.getTransferable().getTransferData(DataFlavor.javaFileListFlavor);
                    if (!droppedFiles.isEmpty()) {
                        File file = droppedFiles.get(0);
                        if (file.isDirectory()) {
                            textField.setText(file.getAbsolutePath());
                        } else {
                            textField.setText(file.getParent());
                        }
                    }
                } catch (Exception ex) {
                    log("拖拽错误: " + ex.getMessage());
                }
            }
        });
    }

    private void setupListeners() {
        browseButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                JFileChooser chooser = new JFileChooser();
                chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
                int result = chooser.showOpenDialog(FileRenamer.this);
                if (result == JFileChooser.APPROVE_OPTION) {
                    directoryField.setText(chooser.getSelectedFile().getAbsolutePath());
                }
            }
        });

        renameButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                renameFiles();
            }
        });
    }

    private void renameFiles() {
        String directoryPath = directoryField.getText().trim();
        if (directoryPath.isEmpty()) {
            showErrorMessage("请选择目录");
            return;
        }

        String prefix = prefixField.getText().trim();
        if (prefix.isEmpty()) {
            showErrorMessage("请输入文件前缀");
            return;
        }

        // 验证数字位数输入
        int numberLength;
        try {
            numberLength = Integer.parseInt(digitsField.getText().trim());
            if (numberLength < 1) {
                showErrorMessage("数字位数必须大于0");
                return;
            }
            if (numberLength > 10) {
                showErrorMessage("数字位数不能超过10位");
                return;
            }
        } catch (NumberFormatException e) {
            showErrorMessage("请输入有效的数字位数");
            return;
        }

        File directory = new File(directoryPath);
        if (!directory.exists() || !directory.isDirectory()) {
            showErrorMessage("目录不存在");
            return;
        }

        try {
            List<File> files = getAllFiles(directory);

            if (files.isEmpty()) {
                log("目录中没有找到文件");
                return;
            }

            // 根据选择的排序方式排序
            String sortOrder = (String) sortOrderComboBox.getSelectedItem();
            String namingOrder = (String) namingOrderComboBox.getSelectedItem();

            sortFiles(files, sortOrder);

            // 根据命名顺序决定是否反转列表
            if ("倒序命名".equals(namingOrder)) {
                Collections.reverse(files);
            }

            int totalFiles = files.size();

            // 检查数字位数是否足够
            int requiredDigits = String.valueOf(totalFiles).length();
            if (numberLength < requiredDigits) {
                int result = JOptionPane.showConfirmDialog(this,
                        "文件数量为 " + totalFiles + "，需要至少 " + requiredDigits + " 位数字，当前设置为 " + numberLength + " 位。是否继续？",
                        "数字位数不足", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
                if (result != JOptionPane.YES_OPTION) {
                    return;
                }
            }

            log("开始重命名 " + files.size() + " 个文件...");
            log("使用前缀: " + prefix + ", 数字位数: " + numberLength);
            log("排序方式: " + sortOrder + ", 命名顺序: " + namingOrder);
            log("----------------------------------------");

            boolean success = true;
            int counter = 0;

            // 先检查是否有命名冲突
            List<File> renameOperations = new ArrayList<>();
            for (File file : files) {
                String extension = getFileExtension(file.getName());
                String newName = String.format("%s_%0" + numberLength + "d%s",
                        prefix, counter, extension);
                File newFile = new File(file.getParent(), newName);

                if (newFile.exists() && !newFile.equals(file)) {
                    log("错误: 目标文件已存在: " + newName);
                    return;
                }
                renameOperations.add(newFile);
                counter++;
            }

            // 执行重命名
            counter = 0;
            for (int i = 0; i < files.size(); i++) {
                File file = files.get(i);
                File newFile = renameOperations.get(i);

                boolean renamed = file.renameTo(newFile);
                if (renamed) {
                    log("✓ " + file.getName() + " → " + newFile.getName());
                } else {
                    log("✗ 重命名失败: " + file.getName());
                    success = false;

                    // 提供更多错误信息
                    if (!file.exists()) {
                        log("  原因: 源文件不存在");
                    } else if (newFile.exists()) {
                        log("  原因: 目标文件已存在");
                    } else if (!file.canWrite()) {
                        log("  原因: 没有写入权限");
                    }
                }
                counter++;
            }

            log("----------------------------------------");
            if (success) {
                log("✓ 所有文件重命名完成！");
                JOptionPane.showMessageDialog(this, "文件重命名完成！", "成功",
                        JOptionPane.INFORMATION_MESSAGE);
            } else {
                log("⚠ 部分文件重命名失败！");
                JOptionPane.showMessageDialog(this, "部分文件重命名失败，请查看日志",
                        "警告", JOptionPane.WARNING_MESSAGE);
            }

        } catch (Exception ex) {
            log("❌ 重命名过程中发生错误: " + ex.getMessage());
            showErrorMessage("重命名失败: " + ex.getMessage());
        }
    }

    /**
     * 显示错误消息对话框
     */
    private void showErrorMessage(String message) {
        JOptionPane.showMessageDialog(this, message, "错误", JOptionPane.ERROR_MESSAGE);
    }

    private void sortFiles(List<File> files, String sortOrder) {
        switch (sortOrder) {
            case "按文件名升序":
                Collections.sort(files, new Comparator<File>() {
                    @Override
                    public int compare(File f1, File f2) {
                        return naturalCompare(f1.getName(), f2.getName());
                    }
                });
                break;
            case "按文件名降序":
                Collections.sort(files, new Comparator<File>() {
                    @Override
                    public int compare(File f1, File f2) {
                        return -naturalCompare(f1.getName(), f2.getName());
                    }
                });
                break;

            case "按修改时间升序":
                Collections.sort(files, new Comparator<File>() {
                    @Override
                    public int compare(File f1, File f2) {
                        return Long.compare(f1.lastModified(), f2.lastModified());
                    }
                });
                break;
            case "按修改时间降序":
                Collections.sort(files, new Comparator<File>() {
                    @Override
                    public int compare(File f1, File f2) {
                        return Long.compare(f2.lastModified(), f1.lastModified());
                    }
                });
                break;
        }
    }

    private List<File> getAllFiles(File directory) {
        List<File> files = new ArrayList<>();
        File[] fileList = directory.listFiles();

        if (fileList != null) {
            for (File file : fileList) {
                if (file.isFile() && !file.isHidden()) {
                    files.add(file);
                }
            }
        }

        return files;
    }

    private String getFileExtension(String filename) {
        int lastDotIndex = filename.lastIndexOf('.');
        if (lastDotIndex > 0 && lastDotIndex < filename.length() - 1) {
            return filename.substring(lastDotIndex);
        }
        return "";
    }

    private void log(String message) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                // 使用平台默认换行符，确保跨平台兼容性
                logArea.append(message + System.lineSeparator());
                logArea.setCaretPosition(logArea.getDocument().getLength());
            }
        });
    }

    public static void main(String[] args) {
        // 在启动时设置系统属性，防止乱码
        System.setProperty("file.encoding", "UTF-8");

        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                try {
                    // 设置系统外观
                    UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());
                } catch (Exception e) {
                    System.err.println("设置外观失败: " + e.getMessage());
                }
                new FileRenamer().setVisible(true);
            }
        });
    }

    // 自然排序比较器
    private int naturalCompare(String s1, String s2) {
        int i = 0, j = 0;
        while (i < s1.length() && j < s2.length()) {
            char c1 = s1.charAt(i);
            char c2 = s2.charAt(j);

            // 如果都是数字，则按数字大小比较
            if (Character.isDigit(c1) && Character.isDigit(c2)) {
                int num1 = 0, num2 = 0;

                while (i < s1.length() && Character.isDigit(s1.charAt(i)))
                    num1 = num1 * 10 + (s1.charAt(i++) - '0');

                while (j < s2.length() && Character.isDigit(s2.charAt(j)))
                    num2 = num2 * 10 + (s2.charAt(j++) - '0');

                if (num1 != num2)
                    return num1 - num2;

            } else {
                // 否则按字符比较
                if (c1 != c2)
                    return c1 - c2;

                i++;
                j++;
            }
        }
        return s1.length() - s2.length();
    }


}

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
Android Prebuilt APK Module Generator

功能:
1. 扫描当前目录APK
2. 创建同名目录
3. 移动APK进入目录
4. 生成Android.mk
5. 生成PRODUCT_PACKAGES列表
"""


import os
import shutil
import sys
import traceback


APK_SUFFIX = ".apk"

ANDROID_MK_NAME = "Android.mk"

PRODUCT_FILE = "product_packages.mk"


ANDROID_MK_TEMPLATE = """LOCAL_PATH := $(call my-dir)

include $(CLEAR_VARS)

LOCAL_MODULE := {module_name}
LOCAL_MODULE_TAGS := optional
LOCAL_SRC_FILES := $(LOCAL_MODULE).apk
LOCAL_MODULE_CLASS := APPS
LOCAL_MODULE_SUFFIX := $(COMMON_ANDROID_PACKAGE_SUFFIX)
LOCAL_CERTIFICATE := PRESIGNED
LOCAL_DEX_PREOPT := false
LOCAL_MODULE_PATH := $(TARGET_OUT)/preloadapp

include $(BUILD_PREBUILT)
"""


def log(msg):
    print("[INFO]", msg)


def error(msg):
    print("[ERROR]", msg)



def get_module_name(filename):

    if not filename.lower().endswith(APK_SUFFIX):
        return None


    name = filename[:-4]


    if not name:
        return None


    # Android module安全处理
    name = name.replace("-", "_")
    name = name.replace(" ", "_")


    return name



def create_dir(path):

    try:

        if not os.path.exists(path):
            os.makedirs(path)

        return True


    except Exception as e:

        error(
            f"创建目录失败 {path}: {e}"
        )

        return False



def move_apk(src, dst):

    """
    移动APK
    """

    try:

        # 防止目标已经存在
        if os.path.exists(dst):

            error(
                f"目标APK已存在，跳过移动: {dst}"
            )

            return False


        shutil.move(
            src,
            dst
        )


        return True


    except Exception as e:


        error(
            f"移动APK失败 {src}->{dst}: {e}"
        )

        return False



def create_android_mk(
        module_dir,
        module_name
):

    try:

        mk_file = os.path.join(
            module_dir,
            ANDROID_MK_NAME
        )


        content = ANDROID_MK_TEMPLATE.format(
            module_name=module_name
        )


        with open(
                mk_file,
                "w",
                encoding="utf-8"
        ) as f:

            f.write(content)


        return True


    except Exception as e:


        error(
            f"生成Android.mk失败 {module_name}: {e}"
        )

        return False



def generate_product_packages(
        modules,
        filepath
):

    try:


        with open(
                filepath,
                "w",
                encoding="utf-8"
        ) as f:


            for module in modules:

                f.write(
                    f"PRODUCT_PACKAGES += {module}\n"
                )


        return True


    except Exception as e:


        error(
            f"生成product文件失败: {e}"
        )

        return False



def scan_and_generate(
        current_dir
):

    modules = []


    try:

        files = os.listdir(
            current_dir
        )


    except Exception as e:

        error(
            f"读取目录失败: {e}"
        )

        return modules



    for file in files:


        if not file.lower().endswith(APK_SUFFIX):

            continue



        apk_path = os.path.join(
            current_dir,
            file
        )


        module_name = get_module_name(
            file
        )


        if not module_name:

            error(
                f"非法APK名称:{file}"
            )

            continue



        log(
            f"开始处理:{file}"
        )



        module_dir = os.path.join(
            current_dir,
            module_name
        )


        # 创建目录
        if not create_dir(
                module_dir
        ):
            continue



        target_apk = os.path.join(
            module_dir,
            module_name + APK_SUFFIX
        )



        # 移动APK
        if not move_apk(
                apk_path,
                target_apk
        ):

            continue



        # 生成Android.mk
        if not create_android_mk(
                module_dir,
                module_name
        ):

            continue



        modules.append(
            module_name
        )


        log(
            f"完成:{module_name}"
        )



    return modules



def main():


    try:


        current_dir = os.getcwd()


        log(
            f"当前目录:{current_dir}"
        )


        modules = scan_and_generate(
            current_dir
        )



        if not modules:

            error(
                "没有成功处理任何APK"
            )

            return 1



        product_file = os.path.join(
            current_dir,
            PRODUCT_FILE
        )


        if generate_product_packages(
                modules,
                product_file
        ):


            log(
                "============================"
            )

            log(
                "处理完成"
            )

            log(
                f"APK数量:{len(modules)}"
            )

            log(
                f"生成:{product_file}"
            )

        else:

            return 1



    except Exception:


        error(
            "未知异常"
        )

        traceback.print_exc()

        return 1



    return 0



if __name__ == "__main__":

    sys.exit(
        main()
    )

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import argparse
import html
import re
import sys
import tempfile
from pathlib import Path

try:
    from markdown_it import MarkdownIt
    from mdit_py_plugins.tasklists import tasklists_plugin
    from mdit_py_plugins.footnote import footnote_plugin
    from pygments import highlight
    from pygments.formatters import HtmlFormatter
    from pygments.lexers import TextLexer, get_lexer_by_name
    from pygments.util import ClassNotFound
    from playwright.sync_api import sync_playwright
except ImportError as e:
    print("缺少依赖，请执行：")
    print("python -m pip install markdown-it-py mdit-py-plugins pygments playwright linkify-it-py")
    print("python -m playwright install chromium")
    print(f"导入失败：{e}")
    sys.exit(1)


def read_markdown(path: Path) -> str:
    for encoding in ("utf-8", "utf-8-sig", "gb18030", "gbk"):
        try:
            return path.read_text(encoding=encoding)
        except UnicodeDecodeError:
            pass
    raise RuntimeError(f"无法识别文件编码：{path}")


def slugify(text: str) -> str:
    text = re.sub(r"<[^>]+>", "", text)
    text = html.unescape(text).strip().lower()
    text = re.sub(r"\s+", "-", text)
    text = re.sub(r"[^a-z0-9\u4e00-\u9fff\-_]+", "", text)
    return text or "heading"


def clean_heading(text: str) -> str:
    text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    text = re.sub(r"[*_~]", "", text)
    return text.strip()


def extract_headings(md_text: str):
    headings = []
    used = {}
    in_code = False

    for line in md_text.splitlines():
        stripped = line.strip()

        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_code = not in_code
            continue

        if in_code:
            continue

        match = re.match(r"^(#{1,6})\s+(.+?)\s*#*\s*$", line)
        if not match:
            continue

        level = len(match.group(1))
        title = clean_heading(match.group(2))
        base_id = slugify(title)

        count = used.get(base_id, 0)
        used[base_id] = count + 1
        heading_id = base_id if count == 0 else f"{base_id}-{count + 1}"

        headings.append({
            "level": level,
            "title": title,
            "id": heading_id,
        })

    return headings


def add_heading_ids(html_text: str, headings):
    index = 0

    def repl(match):
        nonlocal index
        tag = match.group(1)
        attrs = match.group(2) or ""
        content = match.group(3)

        if " id=" in attrs:
            return match.group(0)

        if index < len(headings):
            heading_id = headings[index]["id"]
            index += 1
        else:
            heading_id = slugify(re.sub(r"<[^>]+>", "", content))

        return f'<{tag}{attrs} id="{heading_id}">{content}</{tag}>'

    return re.sub(
        r"<(h[1-6])([^>]*)>(.*?)</\1>",
        repl,
        html_text,
        flags=re.IGNORECASE | re.DOTALL,
    )


def build_toc(headings):
    if not headings:
        return ""

    items = []
    for h in headings:
        indent = max(h["level"] - 1, 0) * 18
        title = html.escape(h["title"])
        heading_id = h["id"]
        items.append(
            f'<div class="toc-item" style="padding-left:{indent}px">'
            f'<a href="#{heading_id}">{title}</a>'
            f'</div>'
        )

    return f"""
<section class="toc-page">
    <h1>目录</h1>
    <div class="toc">
        {''.join(items)}
    </div>
</section>
"""


def highlight_code(code: str, lang: str, attrs: str) -> str:
    lang = (lang or "").strip()
    try:
        lexer = get_lexer_by_name(lang) if lang else TextLexer()
    except ClassNotFound:
        lexer = TextLexer()

    formatter = HtmlFormatter(nowrap=False)
    return highlight(code, lexer, formatter)


def render_markdown(md_text: str) -> str:
    md = (
        MarkdownIt(
            "commonmark",
            {
                "html": True,
                "linkify": True,
                "typographer": True,
                "highlight": highlight_code,
            },
        )
        .enable("table")
        .enable("strikethrough")
        .use(tasklists_plugin, enabled=True)
        .use(footnote_plugin)
    )

    return md.render(md_text)


def build_css() -> str:
    pygments_css = HtmlFormatter(style="default").get_style_defs(".highlight")

    return f"""
@page {{
    size: A4;
    margin: 18mm 15mm 18mm 15mm;
}}

* {{
    box-sizing: border-box;
}}

html {{
    font-family:
        "Microsoft YaHei",
        "微软雅黑",
        "SimSun",
        "宋体",
        "SimHei",
