def build_html(title: str, body_html: str, toc_html: str, show_title_page: bool) -> str:
    title_escaped = html.escape(title)

    title_page = ""
    if show_title_page:
        title_page = f"""
<section class="title-page">
    <h1>{title_escaped}</h1>
</section>
"""

    return f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<title>{title_escaped}</title>
<style>
{build_css()}
</style>
</head>
<body>
{title_page}
{toc_html}
<main>
{body_html}
</main>
</body>
</html>
"""


def convert(input_md: Path, output_pdf: Path, title: str | None, no_toc: bool, no_title_page: bool):
    input_md = input_md.resolve()
    output_pdf = output_pdf.resolve()

    if not input_md.exists():
        raise FileNotFoundError(f"Markdown 文件不存在：{input_md}")

    output_pdf.parent.mkdir(parents=True, exist_ok=True)

    md_text = read_markdown(input_md)
    title = title or input_md.stem

    headings = extract_headings(md_text)
    body_html = render_markdown(md_text)
    body_html = add_heading_ids(body_html, headings)
    toc_html = "" if no_toc else build_toc(headings)

    html_text = build_html(
        title=title,
        body_html=body_html,
        toc_html=toc_html,
        show_title_page=not no_title_page,
    )

    temp_html = None

    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            suffix=".html",
            prefix=".md_to_pdf_",
            dir=str(input_md.parent),
            delete=False,
        ) as f:
            f.write(html_text)
            temp_html = Path(f.name).resolve()

        with sync_playwright() as p:
            browser = p.chromium.launch(headless=True)
            page = browser.new_page()
            page.goto(temp_html.as_uri(), wait_until="networkidle")
            page.pdf(
                path=str(output_pdf),
                format="A4",
                print_background=True,
                prefer_css_page_size=True,
                margin={
                    "top": "18mm",
                    "right": "15mm",
                    "bottom": "18mm",
                    "left": "15mm",
                },
            )
            browser.close()

    finally:
        if temp_html and temp_html.exists():
            try:
                temp_html.unlink()
            except OSError:
                pass

    print(f"转换完成：{output_pdf}")


def main():
    parser = argparse.ArgumentParser(description="Markdown 转 PDF，Windows 友好版。")
    parser.add_argument("input", help="输入 Markdown 文件")
    parser.add_argument("output", help="输出 PDF 文件")
    parser.add_argument("--title", default=None, help="PDF 标题")
    parser.add_argument("--no-toc", action="store_true", help="不生成目录")
    parser.add_argument("--no-title-page", action="store_true", help="不生成封面")
    args = parser.parse_args()

    convert(
        input_md=Path(args.input),
        output_pdf=Path(args.output),
        title=args.title,
        no_toc=args.no_toc,
        no_title_page=args.no_title_page,
    )


if __name__ == "__main__":
    main()

